//! Consumer demonstration: the generator story (plan §3.2's row for
//! `aeolus-data` — "Generated by `xtask` into committed Rust (phf/
//! trie). Also generates: docs …"). The committed artifacts, the seam
//! they render from, and the drift gate that keeps them honest:
//!
//! ```sh
//! cargo run -p aeolus-data --example codegen_artifacts
//! ```
//!
//! What the seam does NOT do: hand-editing the committed artifacts is
//! meaningless (the drift pins overwrite them); regenerating happens
//! through the driver — `cargo xtask gen-tables`, verified by
//! `cargo xtask verify-tables` and by `tests/codegen.rs` in plain
//! `cargo test`.

use aeolus_data::codegen::{self, GeneratedArtifact};
use aeolus_data::registry::{lookup, lookup_detailed};
use aeolus_data::roots_index;

fn main() {
    // The artifact seam: the stable list the xtask driver walks. Each
    // render is a deterministic function of the committed rows.
    println!("committed artifacts (the `cargo xtask list` surface):");
    for artifact in codegen::artifacts() {
        println!(
            "  {:<14} {:<40} {} bytes",
            artifact.name(),
            artifact.path(),
            artifact.generate().len()
        );
    }

    // The drift gate, from the library side: the committed bytes must
    // equal the regeneration (the same comparison `cargo xtask
    // verify-tables` runs).
    let committed_index = include_str!("../src/roots_index.rs");
    let manifest = env!("CARGO_MANIFEST_DIR");
    let committed_docs =
        std::fs::read_to_string(std::path::Path::new(manifest).join("../../docs/REGISTRY.md"))
            .expect("docs/REGISTRY.md is committed beside the rows");
    println!("\ndrift check (the `cargo xtask verify-tables` behaviour):");
    println!(
        "  roots-index    {}",
        if committed_index == codegen::RootsIndex.generate() {
            "clean"
        } else {
            "DRIFTED — run `cargo xtask gen-tables`"
        }
    );
    println!(
        "  registry-docs  {}",
        if committed_docs == codegen::RegistryDocs.generate() {
            "clean"
        } else {
            "DRIFTED — run `cargo xtask gen-tables`"
        }
    );

    // The index the read side consults: which root does the body
    // address? (The longest dash-aligned prefix that is a root.)
    println!("\nthe generated roots index (the read side's fast path):");
    for body in ["p-4", "rounded-tl-lg", "inset-x-2", "not-a-utility"] {
        match roots_index::longest_prefix(body) {
            Some(entry) => println!(
                "  {body:<16} -> root {:?} ({} row(s): {})",
                entry.root,
                entry.rows.len(),
                entry
                    .rows
                    .iter()
                    .map(|&i| aeolus_data::rows::ROWS[i as usize].group)
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            None => println!("  {body:<16} -> no registered root"),
        }
    }

    // The read side answers exactly what it always did (the linear
    // scan is the differential oracle; the typed miss is unchanged).
    println!("\nthe read side, unchanged in shape (indexed under the hood):");
    let rows: Vec<_> = lookup("p-4").collect();
    println!(
        "  lookup(\"p-4\") -> {} row(s), group {:?}",
        rows.len(),
        rows[0].group
    );
    match lookup_detailed("p-red") {
        Ok(_) => unreachable!("p-red accepts no shape"),
        Err(err) => println!("  lookup_detailed(\"p-red\") -> {err}"),
    }
}
